243	fn descend_path<'a>(
244	    mut table: &'a mut InlineTable,
245	    path: &'a [Key],
246	    dotted: bool,
247	    errors: &mut dyn ErrorSink,
248	) -> Option<&'a mut InlineTable> {
249	    #[cfg(feature = "debug")]
250	    let _scope = TraceScope::new("inline_table::descend_path");
251	    #[cfg(feature = "debug")]
252	    trace(
253	        &format!("key={:?}", path.iter().map(|k| k.get()).collect::<Vec<_>>()),
254	        anstyle::AnsiColor::Blue.on_default(),
255	    );
256	    for key in path.iter() {
257	        table = match table.entry_format(key) {
258	            crate::InlineEntry::Vacant(entry) => {
259	                let mut new_table = InlineTable::new();
260	                new_table.span = key.span();
261	                new_table.set_implicit(true);
262	                new_table.set_dotted(dotted);
263	                entry
264	                    .insert(Value::InlineTable(new_table))
265	                    .as_inline_table_mut()
266	                    .unwrap()
267	            }
268	            crate::InlineEntry::Occupied(entry) => {
269	                match entry.into_mut() {
270	                    Value::InlineTable(ref mut sweet_child_of_mine) => {
271	                        // Since tables cannot be defined more than once, redefining such tables using a
272	                        // [table] header is not allowed. Likewise, using dotted keys to redefine tables
273	                        // already defined in [table] form is not allowed.
274	                        if dotted && !sweet_child_of_mine.is_implicit() {
275	                            let key_span = get_key_span(key).expect("all keys have spans");
276	                            errors.report_error(
277	                                ParseError::new("duplicate key").with_unexpected(key_span),
278	                            );
279	                            return None;
280	                        }
281	                        sweet_child_of_mine
282	                    }
283	                    item => {
284	                        let key_span = get_key_span(key).expect("all keys have spans");
285	                        errors.report_error(
286	                            ParseError::new(format!(
287	                                "cannot extend value of type {} with a dotted key",
288	                                item.type_name()
289	                            ))
290	                            .with_unexpected(key_span),
291	                        );
292	                        return None;
293	                    }
294	                }
295	            }
296	        };
297	    }
298	    Some(table)
299	}
300	
301	fn get_key_span(key: &Key) -> Option<toml_parser::Span> {
302	    key.as_repr()
303	        .and_then(|r| r.span())
304	        .map(|s| toml_parser::Span::new_unchecked(s.start, s.end))
305	}
