27	                | EventKind::ArrayTableOpen
28	                | EventKind::InlineTableOpen
29	                | EventKind::InlineTableClose
30	                | EventKind::ArrayOpen
31	                | EventKind::ArrayClose
32	                | EventKind::Scalar
33	                | EventKind::ValueSep
